function nxEscSlot(v) { return String(v).replace(/&(?!(?:[a-zA-Z][a-zA-Z0-9]{1,31}|#\d{1,7}|#x[0-9a-fA-F]{1,6});)/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function nxRenderBlade(id, slots) { const b = NX_TEMPLATE_BLADES[id]; if (!b) return ''; const t = b.t; return t.replace(/{{__([0-9]+)}}/g, (m, n) => { const v = (slots && slots[+n] !== undefined) ? slots[+n] : b.d[+n]; return v === undefined || v === null ? '' : nxEscSlot(v); }); }
