  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96" width="96" height="96" role="img" aria-label="${ini}"><rect width="96" height="96" rx="22" fill="${P.bg}"/><text x="48" y="61" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-weight="700" font-size="${ini.length > 1 ? 40 : 52}" fill="${P.a}">${ini}</text></svg>`;
