  s = s.replace(/\{\{(HERO|WHY|TEAM|SVC[1-3]|P[1-3]|G[1-8]|R[1-3]|LOGO|BANNER)\}\}/g, (m, k) => nxTplImage(project, k.toLowerCase()));
