// NXCROOM WEBSITE QUALITY ENGINE
// Deterministic, zero-dependency audit + enhancement for generated websites.
// Pure functions; usable identically in the browser (NexusCRM_V4_Hardened.html)
// and in the worker (backend/src/index.js). No network, no DOM API required.
// ─────────────────────────────────────────────────────────────────────────────

function __nxEsc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function __nxEscAttr(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
function __nxEmojiFavicon(emoji) {
  const e = String(emoji || '🚀').slice(0, 4);
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">'
    + '<text y=".9em" font-size="90">' + __nxEsc(e) + '</text></svg>';
  return 'data:image/svg+xml,' + encodeURIComponent(svg);
}

// Lighthouse-style weightings (0..1). Sum = 1.
const NX_QUALITY_CATS = [
  { id: 'seo',    name: 'SEO',            weight: 0.30 },
  { id: 'perf',   name: 'Performance',    weight: 0.25 },
  { id: 'a11y',   name: 'Accessibility',  weight: 0.20 },
  { id: 'best',   name: 'Best Practices', weight: 0.15 },
  { id: 'mobile', name: 'Mobile',         weight: 0.10 },
];

function __nxGrade(score) {
  if (score >= 90) return 'A+';
  if (score >= 80) return 'A';
  if (score >= 70) return 'B';
  if (score >= 60) return 'C';
  if (score >= 50) return 'D';
  if (score >= 40) return 'E';
  return 'F';
}

// Audit an HTML string → { score, grade, categories, issues, checks }.
function auditSiteHtml(html) {
  const s = String(html || '');
  const low = s.toLowerCase();
  const cats = {};
  const flatChecks = {};
  const allIssues = [];

  function add(catId, name, max, cond, sev, msg) {
    const pass = !!cond;
    const c = cats[catId] = cats[catId] || { checks: [], issues: [], points: 0, total: 0 };
    c.checks.push({ name, pass, max });
    c.total += max;
    if (pass) c.points += max;
    flatChecks[name] = { pass, pts: pass ? max : 0, max };
    if (!pass) {
      const it = { id: name, cat: catId, severity: sev, message: msg };
      c.issues.push(it);
      allIssues.push(it);
    }
  }

  // ── locators ──────────────────────────────────────────────────────────────
  const head = (s.match(/<head[\s>][\s\S]*?<\/head>/i) || [''])[0] || (s.match(/<head[\s>][\s\S]*/i) || [''])[0];
  const headLow = head.toLowerCase();
  const title = (s.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '';
  const titleLen = title.trim().length;
  const desc = (s.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["'][^>]*>/i) || [])[1]
    || (s.match(/<meta[^>]*content=["']([^"']*)["'][^>]*name=["']description["'][^>]*>/i) || [])[1] || '';
  const htmlLang = /<html[^>]*\blang\s*=/.test(s);
  const imgs = s.match(/<img\b[^>]*>/gi) || [];
  const imgNoAlt = imgs.filter(t => !/<img\b[^>]*\balt\s*=/.test(t) && !/<img\b[^>]*\baria-label\s*=/.test(t)).length;
  const imgLazy = imgs.filter(t => /<img\b[^>]*\bloading\s*=\s*["']lazy/.test(t)).length;
  const imgDim = imgs.filter(t => !/<img\b[^>]*\b(width|height)\s*=/.test(t) && !/<img\b[^>]*\bstyle\s*=/.test(t)).length;
  const hasSrcset = /<img\b[^>]*\bsrcset\s*=/.test(s);
  const isGoogleFonts = /fonts\.googleapis\.com|fonts\.gstatic\.com/.test(low);
  const hasFontPreconnect = /fonts\.googleapis\.com/.test(low) && /rel=["']preconnect["']/.test(low) && /<link[^>]*preconnect[^>]*fonts\.gstatic\.com/i.test(low);
  const fontSwap = /display\s*=\s*swap|&display=swap|font-display:\s*swap/i.test(s);
  const styleInHead = (() => {
    const headEnd = s.toLowerCase().indexOf('</head>');
    const firstStyle = s.toLowerCase().indexOf('<style>');
    return firstStyle === -1 || (headEnd !== -1 && firstStyle < headEnd);
  })();
  const hasDocWrite = /document\.write|document\.writeln/i.test(s);
  const hasDefer = /<script[^>]*\bdefer\b|type=["']module["']/i.test(s);
  const scriptsAtEnd = /<\/head>[\s\S]*<script[\s>][\s\S]*<\/body>/i.test(s);
  const controls = s.match(/<(input|textarea|select)\b[^>]*>/gi) || [];
  const controlsLabeled = controls.filter(t => {
    if (/<(input|textarea|select)\b[^>]*\baria-label\s*=/.test(t)) return true;
    const id = (t.match(/\bid\s*=\s*["']([^"']+)["']/i) || [])[1];
    if (!id) return false;
    return new RegExp('<label[^>]*\\bfor\\s*=\\s*["\']' + id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '["\']', 'i').test(s);
  }).length;
  const buttons = s.match(/<button\b[^>]*>[\s\S]*?<\/button>/gi) || [];
  const btnOK = buttons.filter(t => t.replace(/<[^>]+>/g, '').trim().length > 0 || /aria-label\s*=/.test(t)).length;
  const tabPos = /tabindex\s*=\s*["'][1-9][0-9]*["']/.test(s);
  const hasFocusStyle = /:focus-visible|:focus\b|outline\s*:\s*[^;]+/.test(s);
  const hasReducedMotion = /prefers-reduced-motion/.test(s);
  const hasMedia = /@media\b/.test(s);
  const hasResponsiveGrid = /grid-template-columns\s*:\s*[^;]*(auto-fit|minmax)/i.test(s) || /flex-wrap\s*:\s*wrap/i.test(s) || /\b@media\b/.test(s);
  const hasTouch = /min-height\s*:\s*4[0-9]px|padding\s*:\s*[^;]*\b(12|16|20)px\b/i.test(s) || /\.btn\s*\{[^}]*padding/i.test(s);
  const viewport = /<meta[^>]*name=["']viewport["'][^>]*content=["'][^"']*\bwidth\s*=\s*device-width/i.test(s);
  const initScale = /<meta[^>]*name=["']viewport["'][^>]*content=["'][^"']*\binitial-scale/i.test(s);
  const noopener = /rel=["'][^"']*\bnoopener\b[^"']*["']/i.test(s);
  const anchorsBlank = s.match(/<a\b[^>]*\btarget\s*=\s*["']_blank["'][^>]*>/gi) || [];
  const blankNoNoopener = anchorsBlank.filter(t => !/rel=["'][^"']*\bnoopener\b[^"']*["']/.test(t)).length;
  const extHttpHrefs = (s.match(/<a\b[^>]*\bhref\s*=\s*["']http:\/\/(?!localhost|127\.0\.0\.1|api\.)[^"']*["'][^>]*>/gi) || []).length;
  const extHttpSrcs = (s.match(/<(img|script|link|iframe|source)\b[^>]*\bsrc(?:set)?\s*=\s*["']http:\/\/(?!localhost|127\.0\.0\.1|api\.)[^"']*["'][^>]*>/gi) || []).length;
  const jsonld = (s.match(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi) || []);
  const jsonldType = /"@type"\s*:\s*"(LocalBusiness|Organization|ProfessionalService|Restaurant|Store|MedicalBusiness)".*/.test(jsonld.join('')) ? 'business' : (jsonld.length ? 'other' : 'none');
  const semantic = (['<main', '<header', '<footer', '<nav', '<section', '<article'].filter(tag => low.includes(tag)).length);
  const ogTitle = /property=["']og:title["']/.test(s) || /name=["']og:title["']/.test(s);
  const ogDesc = /property=["']og:description["']/.test(s) || /name=["']og:description["']/.test(s);
  const ogImg = /property=["']og:image["']/.test(s);
  const twCard = /name=["']twitter:card["']/.test(s);
  const canonical = /rel=["']canonical["']/.test(s);
  const favicon = /rel=["']icon["']|\bicon\b/.test(low);
  const robotsMeta = /<meta[^>]*name=["']robots["']/.test(s);
  const colorScheme = /name=["']color-scheme["']/.test(s);
  const themeColor = /name=["']theme-color["']/.test(s);
  const viewportPresent = /name=["']viewport["']/.test(s);
  const charset = /charset\s*=|<meta[^>]*charset/i.test(s);
  const h1s = (s.match(/<h1\b[^>]*>/gi) || []).length;
  const h2s = (s.match(/<h2\b[^>]*>/gi) || []).length;

  // ── SEO ────────────────────────────────────────────────────────────────────
  add('seo', 'title', 3, /<title[^>]*>[\s\S]*<\/title>/i.test(s), 'high', 'Every page needs a <title>.');
  add('seo', 'title_len', 2, titleLen >= 10 && titleLen <= 70, 'medium', 'Title should be 10–70 characters (currently ' + titleLen + ').');
  add('seo', 'description', 2, /<meta[^>]*name=["']description["']/i.test(s) && desc.length >= 30, 'high', 'Add a meta description (30–200 chars) that summarises the page.');
  add('seo', 'description_len', 1, desc.length >= 40 && desc.length <= 200, 'low', 'Description should be 40–200 characters (currently ' + desc.length + ').');
  add('seo', 'charset', 1, charset, 'low', 'Declare <meta charset="utf-8">.');
  add('seo', 'viewport', 1, viewportPresent, 'high', 'Add a Responsive viewport meta tag.');
  add('seo', 'lang', 2, htmlLang, 'medium', 'Set lang="..." on <html> for screen readers & SEO.');
  add('seo', 'canonical', 2, canonical, 'medium', 'Add <link rel="canonical"> to avoid duplicate-content issues.');
  add('seo', 'og_title', 1, ogTitle, 'medium', 'Add og:title for rich social sharing.');
  add('seo', 'og_description', 1, ogDesc, 'medium', 'Add og:description for rich social sharing.');
  add('seo', 'og_image', 1, ogImg, 'low', 'Add og:image so shares get a preview thumbnail.');
  add('seo', 'twitter_card', 1, twCard, 'low', 'Add twitter:card meta for better link previews.');
  add('seo', 'h1', 1, h1s >= 1, 'medium', 'Include a single <h1> as the main heading.');
  add('seo', 'h1_single', 1, h1s === 1, 'low', 'Use exactly one <h1> (currently ' + h1s + ').');
  add('seo', 'h2', 1, h2s >= 1, 'low', 'Organise sections with <h2> sub-headings.');
  add('seo', 'favicon', 1, favicon, 'low', 'Add a favicon (<link rel="icon">).');
  add('seo', 'jsonld', 2, jsonld.length > 0, 'medium', 'Add JSON-LD structured data for rich results.');
  add('seo', 'jsonld_business', 1, jsonldType === 'business', 'low', 'Use a LocalBusiness/Organization @type in JSON-LD.');
  add('seo', 'robots', 1, robotsMeta, 'low', 'Add <meta name="robots" content="index,follow">.');

  // ── Performance ────────────────────────────────────────────────────────────
  add('perf', 'font_preconnect', 2, !isGoogleFonts || (hasFontPreconnect && /preconnect/.test(low)), 'medium', 'Preconnect to fonts.googleapis.com / fonts.gstatic.com when a web font is used.');
  add('perf', 'font_swap', 2, !isGoogleFonts || fontSwap, 'medium', 'Use display=swap (Google Fonts) / font-display:swap so text renders during font load.');
  add('perf', 'css_in_head', 2, styleInHead, 'medium', 'Keep <style> in <head>, not the <body>.');
  add('perf', 'img_dimensions', 2, imgDim === 0 || imgs.length === 0, 'medium', imgDim ? (imgDim + ' <img> lack width/height/ratio → layout shift (CLS).') : '');
  add('perf', 'lazy_images', 2, imgs.length === 0 || (imgLazy / imgs.length) >= 0.6, 'low', 'Add loading="lazy" to below-the-fold images.');
  add('perf', 'responsive_images', 1, hasSrcset, 'low', 'Use srcset for responsive images.');
  add('perf', 'defer_scripts', 1, hasDefer || scriptsAtEnd, 'medium', 'Load scripts asynchronously (defer/type=module) or before </body>.');
  add('perf', 'no_document_write', 2, !hasDocWrite, 'high', 'Avoid document.write (blocks rendering).');
  add('perf', 'no_mixed_http', 2, extHttpSrcs === 0, 'medium', extHttpSrcs + ' external resource(s) loaded over http:// — HTTPS improves speed & trust.');

  // ── Accessibility ──────────────────────────────────────────────────────────
  add('a11y', 'img_alt', 3, imgNoAlt === 0, 'high', imgNoAlt ? (imgNoAlt + ' image(s) missing alt text.') : '');
  add('a11y', 'lang', 2, htmlLang, 'high', 'Set lang="..." on <html> for correct screen-reader pronunciation.');
  add('a11y', 'focus_styles', 2, hasFocusStyle, 'medium', 'Add :focus-visible/:focus styles so keyboard users can see focus.');
  add('a11y', 'reduced_motion', 2, hasReducedMotion, 'medium', 'Respect prefers-reduced-motion (disable heavy animation).');
  add('a11y', 'button_text', 2, btnOK === buttons.length, 'high', (buttons.length - btnOK) + ' button(s) have no accessible text/aria-label.');
  add('a11y', 'form_labels', 2, controls.length === 0 || controlsLabeled === controls.length, 'high', 'Associate every input with a <label> or aria-label.');
  add('a11y', 'no_positive_tabindex', 1, !tabPos, 'medium', 'Avoid positive tabindex values.');
  add('a11y', 'semantic_landmarks', 1, semantic >= 2, 'low', 'Use semantic landmarks (<header>/<nav>/<main>/<footer>/<section>).');

  // ── Best Practices ─────────────────────────────────────────────────────────
  add('best', 'noopener', 2, blankNoNoopener === 0, 'medium', blankNoNoopener + ' target="_blank" link(s) missing rel="noopener".');
  add('best', 'https_links', 1, extHttpHrefs === 0, 'medium', extHttpHrefs + ' link(s) use http:// — prefer https:// (avoid mixed content).');
  add('best', 'color_scheme', 1, colorScheme, 'low', 'Add <meta name="color-scheme"> for consistent dark-mode form rendering.');
  add('best', 'theme_color', 1, themeColor, 'low', 'Add <meta name="theme-color"> for branded mobile browser chrome.');

  // ── Mobile ─────────────────────────────────────────────────────────────────
  add('mobile', 'viewport', 2, viewport, 'high', 'Set the viewport meta to width=device-width.');
  add('mobile', 'initial_scale', 2, initScale, 'medium', 'Keep initial-scale for correct zoom on phones.');
  add('mobile', 'media_queries', 2, hasMedia, 'medium', 'Add @media queries for responsive layout.');
  add('mobile', 'responsive_grid', 2, hasResponsiveGrid, 'medium', 'Use fluid grids (auto-fit/minmax or flex-wrap) so columns stack.');
  add('mobile', 'touch_targets', 2, hasTouch, 'medium', 'Size tap targets ≥ ~44px (padding/min-height on buttons).');

  // ── fold into report ───────────────────────────────────────────────────────
  const categories = NX_QUALITY_CATS.map(c => {
    const cc = cats[c.id] || { checks: [], issues: [], points: 0, total: 1 };
    const maxTotal = cc.total || 1;
    const pct = Math.round((cc.points / maxTotal) * 100);
    return {
      id: c.id, name: c.name, weight: c.weight,
      score: Math.min(100, pct), points: cc.points, total: maxTotal,
      issues: cc.issues, checks: cc.checks,
    };
  });
  let weighted = 0, weightSum = 0;
  categories.forEach(c => { weighted += c.score * c.weight; weightSum += c.weight; });
  const score = Math.round(weighted / (weightSum || 1));
  const orderedIssues = allIssues.sort((a, b) => {
    const rank = { high: 0, medium: 1, low: 2 };
    return (rank[a.severity] - rank[b.severity]) || a.cat.localeCompare(b.cat);
  });
  return { score, grade: __nxGrade(score), categories, issues: orderedIssues, checks: flatChecks };
}

// Improve an HTML string so it passes the audit. Idempotent: never duplicates
// meta it already has. Safe for any HTML with a <head> or <html>.
function enhanceSiteHtml(html, name, opts) {
  opts = opts || {};
  const siteName = String(opts.name || name || 'My Website').slice(0, 100);
  const description = String(opts.description || '').slice(0, 200);
  const lang = String(opts.lang || 'en').slice(0, 10);
  const favicon = String(opts.favicon || '🚀').slice(0, 4);
  const canonical = String(opts.canonical || '').trim();
  let s = String(html || '').trim();

  if (!s || !/<html|<!doctype/i.test(s)) {
    s = '<!DOCTYPE html><html lang="' + __nxEscAttr(lang) + '"><head><meta charset="utf-8">'
      + '<meta name="viewport" content="width=device-width, initial-scale=1"></head>'
      + '<body><main><h1>' + __nxEsc(siteName) + '</h1></main></body></html>';
  }
  if (!/<!doctype\s+html/i.test(s)) s = s.replace(/^\s*/, '').replace(/^/i, '<!DOCTYPE html>\n');

  // Derivative content for meta we may need to inject.
  const h1Text = (s.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i) || [])[1] || '';
  const firstText = (s.match(/<p\b[^>]*>([\s\S]*?)<\/p>/i) || [])[1] || '';
  const titleVal = (s.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '';
  // <title> content is HTML text (entity-encoded); decode it before it is re-escaped
  // into og:title / JSON-LD, otherwise "&amp;" becomes "&amp;amp;" on every save.
  const titleIn = nxDecodeEntities(titleVal.trim()) || siteName;
  const descIn = description || h1Text.replace(/<[^>]+>/g, '').trim() || firstText.replace(/<[^>]+>/g, '').trim() || titleIn;

  // <html lang>
  if (/<html\b/i.test(s)) {
    s = s.replace(/<html(\s[^>]*)?>/i, m => /\blang\s*=/.test(m) ? m : m.replace(/<html/i, '<html lang="' + __nxEscAttr(lang) + '"'));
  } else {
    s = s.replace(/^[\s\S]*?(<!doctype[^>]*>?)?/i, '$1\n<html lang="' + __nxEscAttr(lang) + '">');
  }

  // Ensure a <head> block exists.
  if (!/<head[\s>]/i.test(s)) {
    s = s.replace(/<html\b[^>]*>/i, m => m + '\n<head></head>');
  }

  // A single block of head additions, conditionally produced.
  let headAdd = '';
  const hasCharset = /<meta[^>]*charset\s*=/i.test(s);
  const hasViewport = /<meta[^>]*name=["']viewport["']/i.test(s);
  const hasTitle = /<title[^>]*>[\s\S]*<\/title>/i.test(s);
  const hasDesc = /<meta[^>]*name=["']description["']/i.test(s);
  if (!hasCharset) headAdd += '<meta charset="utf-8">\n';
  if (!hasViewport) headAdd += '<meta name="viewport" content="width=device-width, initial-scale=1">\n';
  if (!hasTitle) headAdd += '<title>' + __nxEsc(titleIn) + '</title>\n';
  if (!hasDesc) headAdd += '<meta name="description" content="' + __nxEscAttr(descIn.slice(0, 200)) + '">\n';
  if (!/name=["']robots["']/i.test(s)) headAdd += '<meta name="robots" content="index,follow">\n';
  if (!/name=["']theme-color["']/i.test(s)) headAdd += '<meta name="theme-color" content="' + __nxEscAttr(opts.theme_color || '#0b0e14') + '">\n';
  if (!/name=["']color-scheme["']/i.test(s)) headAdd += '<meta name="color-scheme" content="light dark">\n';
  if (!/property=["']og:title["']|name=["']og:title["']/i.test(s)) headAdd += '<meta property="og:title" content="' + __nxEscAttr(titleIn) + '">\n';
  if (!/property=["']og:type["']|name=["']og:type["']/i.test(s)) headAdd += '<meta property="og:type" content="website">\n';
  if (!/property=["']og:description["']|name=["']og:description["']/i.test(s)) headAdd += '<meta property="og:description" content="' + __nxEscAttr(descIn.slice(0, 200)) + '">\n';
  if (opts.image && !/property=["']og:image["']|name=["']og:image["']/i.test(s)) headAdd += '<meta property="og:image" content="' + __nxEscAttr(opts.image) + '">\n';
  if (!/name=["']twitter:card["']/.test(s)) headAdd += '<meta name="twitter:card" content="summary_large_image">\n';
  if (canonical && !/rel=["']canonical["']/i.test(s)) headAdd += '<link rel="canonical" href="' + __nxEscAttr(canonical) + '">\n';
  if (!/rel=["']icon["']|\bbase_url_favicon\b|apple-touch-icon/i.test(s)) headAdd += '<link rel="icon" href="' + __nxEscAttr(__nxEmojiFavicon(favicon)) + '"><link rel="apple-touch-icon" href="' + __nxEscAttr(__nxEmojiFavicon(favicon)) + '">\n';

  // Preconnect for Google Fonts (only if the page uses them but has no preconnect).
  if (!/rel=["']preconnect["']/i.test(s) && /fonts\.googleapis\.com|fonts\.gstatic\.com/i.test(s)) {
    headAdd += '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n';
  }

  // A page with NO <style> at all has no responsive/accessible styling. Inject a
  // minimal, non-intrusive base layer (focus rings, reduced-motion, responsive
  // media, touch targets). Guarded so a themed page is never touched.
  if (!/<style\b/i.test(s)) {
    headAdd += '<style>'
      + '*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;line-height:1.6;color:#1e293b}'
      + ':focus-visible{outline:3px solid currentColor;outline-offset:2px}'
      + 'img{max-width:100%;height:auto;display:block}'
      + 'a,button{min-height:44px;display:inline-flex;align-items:center;justify-content:center}'
      + '@media (prefers-reduced-motion: reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}'
      + '@media (max-width:768px){h1{font-size:1.6em}h2{font-size:1.35em}}'
      + '</style>\n';
  }

  // Structured data — skip if any JSON-LD already present.
  if (!/<script[^>]*type=["']application\/ld\+json["']/i.test(s)) {
    const business = {
      '@context': 'https://schema.org',
      '@type': opts.type === 'restaurant' ? 'Restaurant' : (opts.type === 'store' ? 'Store' : (opts.type === 'medical' ? 'MedicalBusiness' : (opts.type === 'professional' ? 'ProfessionalService' : 'LocalBusiness'))),
      'name': titleIn,
      'description': descIn.slice(0, 180),
      'url': canonical || undefined,
      'image': opts.image || undefined,
      'telephone': opts.phone || undefined,
      'email': opts.email || undefined,
      'address': opts.address ? { '@type': 'PostalAddress', streetAddress: opts.address } : undefined,
    };
    const json = NX_SAFE_HTML.nxJsonForScript(business);
    headAdd += '<script type="application/ld+json">' + json + '<\/script>\n';
  }

  if (headAdd) s = s.replace(/<\/head>/i, headAdd + '</head>');

  // Favicon emoji in the title bar fallback + open-graph absolute fallback handled above.

  // Images: lazy, async decode, alt. Only MARKUP is touched: <script> bodies
  // are skipped (runtimes build <img> tags inside template literals, and a
  // rewrite there corrupts the programme), and a self-closing " />" keeps its
  // slash at the end — attributes appended after it produced broken tags.
  if (/<img\b/i.test(s)) {
    const fixImg = (m, attrs) => {
      let a = attrs.replace(/\s*\/\s*$/, '');
      if (!/\bloading\s*=/i.test(a)) a += ' loading="lazy"';
      if (!/\bdecoding\s*=/i.test(a)) a += ' decoding="async"';
      if (!/\balt\s*=|\baria-label\s*=/i.test(a)) {
        const src = (a.match(/\bsrc\s*=\s*["']([^"']+)["']/i) || [])[1] || '';
        const base = /^data:/i.test(src) ? '' : String(src).split('/').pop().replace(/\.[a-z0-9]+$/i, '').replace(/[-_]+/g, ' ').trim();
        a += base ? ' alt="' + __nxEscAttr(base.slice(0, 120)) + '"' : ' alt=""';
      }
      return '<img' + a + '>';
    };
    s = s.split(/(<script\b[^>]*>[\s\S]*?<\/script>)/i).map((part, i) => (i % 2 ? part : part.replace(/<img\b([^>]*?)>/gi, fixImg))).join('');
  }

  // target="_blank" → rel="noopener noreferrer"
  if (/target\s*=\s*["']_blank["']/i.test(s)) {
    s = s.replace(/<a\b([^>]*\btarget\s*=\s*["']_blank["'][^>]*?)>/gi, (m, attrs) => {
      const rel = (attrs.match(/\brel\s*=\s*["']([^"']*)["']/i) || [])[1] || '';
      if (/\bnoopener\b/i.test(rel)) return '<a' + attrs + '>';
      const newRel = (rel ? rel + ' ' : '') + 'noopener noreferrer';
      if (/\brel\s*=\s*["']/i.test(attrs)) {
        return '<a' + attrs.replace(/\brel\s*=\s*["'][^"']*["']/i, 'rel="' + newRel + '"') + '>';
      }
      return '<a' + attrs + ' rel="' + newRel + '">';
    });
  }

  return s;
}

// If the raw input wasn't HTML at all, wrap it. Used internally.
function minimalDoc(title, body) {
  return '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width, initial-scale=1">'
    + '<title>' + __nxEsc(title || 'Page') + '</title></head>'
    + '<body><h1>' + __nxEsc(title || 'Page') + '</h1>' + (body || '') + '</body></html>';
}

// ── AGENTIC SITE ENGINE (testing agent + debugger + build loop) ──
// ─────────────────────────────────────────────────────────────────────────────
// NXCROOM AGENTIC SITE ENGINE
// The "AI Testing Agent + AI Debugger + build loop" behind the website builder.
// Deterministic, zero-I/O:
//   testSiteHtml(html)  — open the generated page and verify it works
//                         (structure, a11y, perf, SEO, responsive, content),
//                         returning a pass/fail report.
//   debugSiteHtml(html) — diagnose concrete problems (broken anchors, missing
//                         alts, duplicate ids, tag balance, etc.).
//   autoFixSite(html)   — targeted, idempotent fixes beyond the quality pass
//                         (fill alt, eager first image, ensure viewport/lang,
//                         drop orphan nav anchors, add loading).
//   runAgenticLoop(build) — the loop: build → inspect → test → detect → fix →
//                         re-test, capped; returns the final report.
// ─────────────────────────────────────────────────────────────────────────────

// The deterministic testing agent (debugSiteHtml / testSiteHtml / autoFixSite)
// lives in nx_site_agent.js; the loop below consumes it through the same names.
const { debugSiteHtml, testSiteHtml, autoFixSite, NX_AGENT_CATS } = NX_SITE_AGENT;

// The loop: build → inspect → test → detect → fix → re-test (capped).
// `build` must return a Promise<string> (or string) of full HTML.
async function runAgenticLoop(build, ctx) {
  ctx = ctx || {};
  const maxIter = Math.max(1, Math.min(4, ctx.maxIterations || 3));
  let html = await build();
  const trace = [];
  html = html || '';

  // ── BLOCKING STRUCTURAL GATE (fast, deterministic, runs every build) ──
  // Nothing previously verified that emitted markup was structurally sound:
  // an unclosed <div> or a <div> inside a <p> silently changed the rendered
  // layout because the browser repairs it its own way. Parse the document,
  // and if it is malformed, repair it deterministically BEFORE any scoring —
  // heavy semantic auditing stays out of this hot path by design.
  let astGate = null;
  try {
    const __ast = NX_AST_MOD;
    astGate = __ast.nxAstSyntaxGate(html);
    // Only rewrite when the structure is genuinely broken. Re-serializing a
    // healthy document is a no-op semantically but still perturbs formatting
    // (parse5 normalises boolean attributes such as `data-r` to `data-r=""`),
    // and the rendered page is the source of truth — do not touch it needlessly.
    if (!astGate.ok) {
      const rep = __ast.nxAstAutoClose(html);
      if (rep.changed) {
        const after = __ast.nxAstSyntaxGate(rep.html);
        // Never accept a "repair" that leaves the document worse off.
        if (after.errors.length < astGate.errors.length) {
          html = rep.html;
          trace.push({ iter: 0, stage: 'ast-repair', before: astGate.errors.length, after: after.errors.length, errors: astGate.errors.slice(0, 5) });
          astGate = after;
        }
      }
    }
  } catch (e) { logSwallow('build.validation_gate', e, { direction: ctx.direction || '' }); }

  // ── BLOCKING VALIDATION GATE (§5) ──────────────────────────────────────
  // This is a GATE, not a report. Every generation is measured for structural,
  // layout, contrast and copy violations; anything tagged `blocking` triggers
  // automatic, minimal repair and re-measurement, up to the iteration budget.
  // Nothing reaches the caller un-repaired, and if blockers survive the budget
  // we say so explicitly rather than quietly shipping a broken page.
  let validation = null, validationLog = [], validationRepaired = false;
  const __valStart = Date.now();
  try {
    // Phase 1.1: prefer the browser-backed gate. It renders in real Chromium at
    // every required viewport and measures actual geometry; if no browser is
    // available it degrades to approximate mode and flags the output as
    // VISUALLY UNVERIFIED rather than silently claiming verification.
    const gate = (typeof NX_VALIDATE_MOD.nxValidateAndRepairAsync === 'function')
      ? await NX_VALIDATE_MOD.nxValidateAndRepairAsync(() => html, null, { maxIterations: 4 })
      : NX_VALIDATE_MOD.nxValidateAndRepair(() => html, null, { maxIterations: 4 });
    if (gate && gate.html) {
      html = gate.html;
      validation = gate.report;
      validationLog = gate.log;
      validationRepaired = gate.repaired;
    }
  } catch (e) { validation = null; }
  try {
    if (validation) NX_HISTORY_MOD.nxRecordGeneration({
      direction: (ctx && ctx.direction) || '', name: (ctx && ctx.name) || '',
      pass: validation.pass, iterations: validationLog.length, repaired: validationRepaired,
      shippedWithBlockers: !validation.pass,
      blockingRules: validation.blocking.map(b => b.rule),
      warningCount: validation.warnings.length,
      repairs: validationLog.flatMap(l => l.repairs || []),
      ms: Date.now() - __valStart,
      renderer: validation.renderer, browserValidated: validation.browserValidated,
    });
  } catch (e) { logSwallow('build.validation_history', e, { direction: ctx.direction || '' }); }

  let test = testSiteHtml(html);
  trace.push({ iter: 0, score: test.score, status: test.status, issues: test.issues.length });
  let fixed = false;
  for (let i = 1; i <= maxIter; i++) {
    if (test.status === 'pass') break;
    // apply the deterministic fix pass, then verify again
    const next = autoFixSite(html);
    if (next === html) break; // nothing to fix
    const after = testSiteHtml(next);
    // A "fix" that lowers the score is rejected, never shipped (the loop used to keep it: measured 92 → 88 on every composed direction).
    if (after.score < test.score) {
      trace.push({ iter: i, score: after.score, status: after.status, issues: after.issues.length, rejected: true });
      break;
    }
    html = next; fixed = true; test = after;
    trace.push({ iter: i, score: test.score, status: test.status, issues: test.issues.length });
  }
  return { html, test, fixed, iterations: trace.length, trace,
    ast: astGate ? { ok: astGate.ok, errors: astGate.errors } : null,
    validation: validation ? {
      pass: validation.pass,
      blocking: validation.blocking, warnings: validation.warnings,
      perViewport: validation.perViewport, readability: validation.readability,
      // §6: an honest signal that blockers survived the repair budget.
      shippedWithBlockers: !validation.pass,
      repaired: validationRepaired, repairLog: validationLog,
      // Never let a caller believe this was pixel-verified.
      browserValidated: validation.browserValidated, renderer: validation.renderer, note: validation.note,
      // Explicit machine-readable flag for any consumer/UI.
      visuallyUnverified: validation.visuallyUnverified !== false,
      browserReason: validation.browserReason || '',
      engine: validation.engine || '', browserVersion: validation.browserVersion || '',
    } : null };
}

// ── AI VISUAL EDITOR (natural-language element commands) ──
// ─────────────────────────────────────────────────────────────────────────────
// NXCROOM AI VISUAL EDITOR
// 1) nxVisualCommand(instruction, context) — deterministic natural-language →
//    CSS/text action for common edits (size, color, text, bold, align, padding,
//    radius, shadow, hide). Runs locally with NO AI key; optional AI assist can
//    be layered on top for freeform wording.
// 2) nxComputeSelector(element) — a robust, stable CSS selector for a DOM node.
// 3) nxVisualCss(overrides) — joins selector → rules into a <style> body.
// Pure / DOM-optional (selector needs a DOM node); command is pure.
// ─────────────────────────────────────────────────────────────────────────────

const NX_VISUAL_COLORS = {
  orange: '#f7742a', red: '#ef4444', blue: '#3b82f6', green: '#22c55e',
  purple: '#a855f7', pink: '#ec4899', teal: '#14b8a6', yellow: '#eab308',
  black: '#0b0e14', white: '#ffffff', gray: '#64748b', grey: '#64748b',
  navy: '#1e3a8a', gold: '#f5b301', 'dark blue': '#1e3a8a', 'light gray': '#e2e8f0',
};

function _curve(v, factor, unit) {
  const n = parseFloat(v);
  if (!isFinite(n) || n <= 0) return null;
  const out = Math.round(n * factor * 10) / 10;
  return out + (unit || (String(v).replace(/[0-9.,]/g, '') || 'px'));
}
function _pad(v, factor) {
  if (!v) return null;
  const parts = String(v).trim().split(/\s+/);
  const unit = parts[0].replace(/[0-9.,]/g, '') || 'px';
  const u = (s) => _curve(s, factor, unit);
  if (parts.length === 1) return u(parts[0]);
  return parts.map(u).join(' ');
}
function _extractText(raw) {
  // Match explicit "change/set/rename ... to X", "make it/this say X", "say X",
  // "write X", "read X", "label it as X". Case-insensitive but PRESERVES the
  // original capitalization of the captured text. Only fires on a clear verb.
  const m = String(raw).match(/(?:change|set|rename)\b[\s\S]*?\bto\b|make (?:this|it) say|make this say|say\b|write\b|read\b|label it(?: as)?/i);
  if (!m) return null;
  const verb = m[0];
  const idx = String(raw).toLowerCase().indexOf(verb.toLowerCase());
  let rest = String(raw).slice(idx + verb.length);
  // for change/set/rename ... to, strip up to and incl. the trailing "to"
  if (/^(?:change|set|rename)/i.test(verb.trim()) && !/^make|^say|^write|^read|^label/i.test(verb.trim())) {
    const toIdx = rest.toLowerCase().indexOf('to');
    if (toIdx !== -1) rest = rest.slice(toIdx + 2);
  }
  rest = rest.replace(/^[:.\s"']+/, '').replace(/[."'!]+$/, '').trim();
  return rest || null;
}

function nxVisualCommand(instruction, ctx) {
  ctx = ctx || {};
  const cur = ctx.css || {};
  const raw = String(instruction || '').replace(/[.,!]+$/g, '').trim();
  const i = raw.toLowerCase();
  const out = { css: {}, text: null, action: null, summary: '' };
  if (!i) return { error: 'empty' };

  // ── size ──
  let m = i.match(/(?:font-?size|size|text)\s*(?:to|of|=)\s*([0-9.]+)\s*(px|em|rem|%)/);
  if (m) { out.css.fontSize = m[1] + m[2]; out.action = 'size'; }
  else if (/(much |way )?(bigger|larger|huge|increase the size|make (it|this|the (?:text|heading|button)) bigger)/.test(i) || /\b(bigger|larger)\b/.test(i)) {
    const f = /(huge|much bigger|way bigger)/.test(i) ? 1.6 : 1.35;
    const v = _curve(cur.fontSize, f); if (v) { out.css.fontSize = v; out.action = 'size'; }
  }
  else if (/\b(smaller|smaller text|decrease the size|make (it|this) smaller)\b/.test(i)) {
    const v = _curve(cur.fontSize, 0.72); if (v) { out.css.fontSize = v; out.action = 'size'; }
  }

  // ── color / background ──
  const colM = i.match(/\b(navy|dark blue|light gray|orange|red|blue|green|purple|pink|teal|yellow|black|white|gray|grey|gold)\b/);
  const hexM = i.match(/#[0-9a-f]{3,6}\b/i);
  const bg = /background|bg|fill/.test(i);
  if (colM && NX_VISUAL_COLORS[colM[1]]) {
    if (bg) out.css.backgroundColor = NX_VISUAL_COLORS[colM[1]];
    else out.css.color = NX_VISUAL_COLORS[colM[1]];
    out.action = bg ? 'background' : 'color';
  } else if (hexM) {
    if (bg) out.css.backgroundColor = hexM[0]; else out.css.color = hexM[0];
    out.action = bg ? 'background' : 'color';
  }

  // ── weight / style ──
  if (/\bbold\b|make (it|this) bold/.test(i)) { out.css.fontWeight = '700'; out.action = 'weight'; }
  else if (/\bthin\b|light weight|lighter\b/.test(i)) { out.css.fontWeight = '400'; out.action = 'weight'; }
  if (/\bitalic\b/.test(i)) { out.css.fontStyle = 'italic'; out.action = 'style'; }
  if (/\bunderline\b/.test(i)) { out.css.textDecoration = 'underline'; out.action = 'style'; }
  if (/\buppercase|all caps|caps\b/.test(i)) { out.css.textTransform = 'uppercase'; out.action = 'transform'; }

  // ── alignment ──
  if (/\b(center|centred|centered|align center|middle)\b/.test(i)) { out.css.textAlign = 'center'; out.action = 'align'; }
  else if (/\b(right align|align right|justify right)\b/.test(i)) { out.css.textAlign = 'right'; out.action = 'align'; }
  else if (/\b(left align|align left|justify left)\b/.test(i)) { out.css.textAlign = 'left'; out.action = 'align'; }

  // ── spacing / padding / radius / shadow ──
  if (/\bmore padding|add padding|more space|increase padding|spread out\b/.test(i)) { const v = _pad(cur.padding, 1.25); if (v) { out.css.padding = v; out.action = 'padding'; } }
  else if (/\bless padding|reduce padding|less space|tighten\b/.test(i)) { const v = _pad(cur.padding, 0.75); if (v) { out.css.padding = v; out.action = 'padding'; } }
  if (/\brounded|round the corners|round corners\b/.test(i)) { out.css.borderRadius = '16px'; out.action = 'radius'; }
  if (/\bshadow|drop shadow|add depth\b/.test(i)) { out.css.boxShadow = '0 12px 34px rgba(0,0,0,.22)'; out.action = 'shadow'; }

  // ── hide / remove ──
  if (/\b(hide|remove|delete|get rid of|disappear)\b/.test(i)) { out.css.display = 'none'; out.action = 'hide'; }

  // ── text change (lowest priority; only if nothing else matched) ──
  if (!out.action) {
    const t = _extractText(raw);
    if (t) { out.text = t; out.action = 'text'; }
  }

  if (!out.action) return { error: 'unsupported' };
  out.summary = (out.action === 'text') ? ('Text → "' + out.text + '"') : (out.action + ': ' + Object.entries(out.css).map(([k, v]) => k + ' ' + v).join(', '));
  return out;
}

// Robust, stable CSS selector for a DOM element (chromium/jsdom-safe).
function nxComputeSelector(el, root) {
  if (!el || el.nodeType !== 1) return null;
  root = root || document || ((el.ownerDocument && el.ownerDocument.body) || el);
  if (el === root || el === root.body) return 'body';
  // prefer id
  if (el.id) return '#' + _cssEscape(el.id);
  const parts = [];
  let node = el;
  while (node && node !== root && node.nodeType === 1) {
    let seg = node.tagName.toLowerCase();
    const cls = (typeof node.className === 'string' ? node.className : '')
      .trim().split(/\s+/).filter(Boolean)
      .map(c => '.' + _cssEscape(c)).join('');
    // disambiguate among siblings of the same tag+class combo
    const same = node.parentElement ? Array.prototype.filter.call(node.parentElement.children, (s) =>
      s.tagName === node.tagName && (s.className || '') === (node.className || '')) : [node];
    if (same.length > 1) {
      const idx = same.indexOf(node);
      if (idx >= 0) seg += (cls ? '' : '') + ':nth-of-type(' + (idx + 1) + ')';
    }
    parts.unshift(seg + (cls && seg.indexOf(cls) === -1 ? cls : ''));
    node = node.parentElement;
    if (node && node !== root && node.children && node.children.length < 2) break; // avoid over-qualifying
  }
  return parts.join(' > ');
}

// camelCase → kebab-case so style-object keys (fontSize, backgroundColor…) become
// VALID CSS property names in a stylesheet (font-size, background-color…).
function _kebab(k) { return String(k).replace(/([A-Z])/g, '-$1').toLowerCase(); }

// CSS.escape falls back to a manual escape when the global is unavailable
// (jsdom, some embedded runtimes) — ids/classes keep working.
function _cssEscape(s) {
  if (typeof CSS !== 'undefined' && CSS && typeof CSS.escape === 'function') return CSS.escape(s);
  return String(s == null ? '' : s).replace(/[^A-Za-z0-9_-]/g, (c) => '\\' + c);
}

// Join a list of { selector, css } into a CSS body string.
function nxVisualCss(overrides) {
  return (overrides || []).filter(o => o && o.selector && o.css && Object.keys(o.css).length)
    .map(o => o.selector + ' { ' + Object.entries(o.css).map(([k, v]) => _kebab(k) + ':' + v + ';').join(' ') + ' }')
    .join('\n');
}

// Persist a visual CSS block into a site's <head> (idempotent).
function nxVisualApplyCss(html, css) {
  const s = String(html || '');
  const block = '<style data-nx-visual>' + String(css || '') + '</style>';
  if (/<style[^>]*\bdata-nx-visual\b/i.test(s)) return s.replace(/<style[^>]*\bdata-nx-visual\b[^>]*>[\s\S]*?<\/style>/i, block);
  if (/<\/head>/i.test(s)) return s.replace(/<\/head>/i, block + '</head>');
  return s;
}

// Apply a list of visual overrides to an HTML string. Dependency-free (no DOM
// needed — runs in the worker/browser). Each override carries `css` (a style
// block appended via nxVisualApplyCss) and/or `text` (replace the targeted
// element's inner text). Text targets leaf elements matched by trailing #id or
// .class on the selector. Unsupported edits are skipped, never mangled.
function nxVisualApplyEdits(html, overrides) {
  let s = String(html || '');
  const list = (Array.isArray(overrides) ? overrides : [overrides]).filter(Boolean);
  const cssOv = [];
  for (const o of list) {
    if (o && o.selector && o.css && typeof o.css === 'object' && Object.keys(o.css).length) cssOv.push({ selector: o.selector, css: o.css });
  }
  if (cssOv.length) s = nxVisualApplyCss(s, nxVisualCss(cssOv));
  for (const o of list) {
    if (!o || !o.selector || o.text == null) continue;
    const rawSel = String(o.selector).trim();
    const idM = rawSel.match(/#([A-Za-z0-9_-]+)\s*$/);
    const clsM = rawSel.match(/\.([A-Za-z0-9_-]+)\s*$/);
    let openRe = null;
    if (idM) {
      const id = idM[1].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      openRe = new RegExp('<([a-z][a-z0-9]*)\\b[^>]*\\bid\\s*=\\s*[\"\']' + id + '[\"\'][^>]*>', 'i');
    } else if (clsM) {
      const cls = clsM[1].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      openRe = new RegExp('<([a-z][a-z0-9]*)\\b[^>]*\\bclass\\s*=\\s*[\"\'][^\"\']*\\b' + cls + '\\b[^\"\']*[\"\'][^>]*>', 'i');
    }
    if (!openRe) continue;
    const text = __nxEscAttr(String(o.text).slice(0, 400));
    const openMatch = openRe.exec(s);
    if (!openMatch) continue;
    const tag = (openMatch[0].match(/^<([a-z][a-z0-9]*)/i) || [])[1] || 'div';
    const openEnd = openMatch.index + openMatch[0].length;
    const closeRe = new RegExp('</' + tag + '>', 'i');
    const cm = closeRe.exec(s.slice(openEnd));
    if (!cm) continue;
    s = s.slice(0, openEnd) + text + s.slice(openEnd + cm.index);
  }
  return s;
}

async function aiBuildSite(env, ws, body) {
  // UNIFIED BUILD PATH.
  //
  // This route used to be "ask the model for a full HTML document, else emit a
  // static fallback template". That bypassed the entire composition engine, so
  // /ai/build-site produced generic AI-shaped pages with no design direction, no
  // composition plan, no hierarchy/rhythm system and no quality loop — while
  // /ai/agentic-build produced art-directed output from the same brief.
  //
  // It now delegates to the SAME deterministic pipeline. The AI (when configured)
  // enriches content inside that pipeline rather than authoring raw markup, so the
  // design floor never depends on a model being available. The response contract
  // ({ name, html }) is preserved, with design metadata added.
  const name = String(body.name || '').slice(0, 120) || 'My Website';
  const desc = String(body.description || '').slice(0, NX_BRIEF_MAX) || 'A modern business website';
  const built = await buildAgenticSite(env, ws, Object.assign({}, body, { name, description: desc }));
  return {
    name: built.name,
    html: built.html,
    direction: built.direction || '',
    designExplanation: built.designExplanation || '',
    audit: built.audit,
    iterations: built.iterations,
    build: built.build || null,
    ast: built.ast || null,
    validation: built.validation || null,
  };
}
async function buildAgenticSite(env, ws, body) {
  const name = String(body.name || 'My Website').slice(0, 120);
  const desc = String(body.description || '').slice(0, NX_BRIEF_MAX);
  // Deterministic Blueprint plan is always composed and merged, then the model
  // (if available & not disabled) enriches it — the build floor never depends on AI.
  const rep = {};
  const build = async () => generateSiteHtml(env, ws, {
    name, description: desc, design_id: body.design_id, plan: body.plan || null,
    instructions: body.instructions || '', webhook_url: String(body.webhook_url || ''),
    accent: body.accent, accent2: body.accent2, font: body.font, radius: body.radius,
    animation_level: body.animation_level, sections: body.sections,
    custom_css: body.custom_css, favicon: body.favicon,
    theme_id: body.theme_id, hero_style: body.hero_style, anim_preset: body.anim_preset,
    card_style: body.card_style, nav_style: body.nav_style, three_d: body.three_d,
    scene_id: body.scene_id, spline_url: body.spline_url, scene_text: body.scene_text,
    direction: body.direction,
    auto_design: body.auto_design,
    widgets: body.widgets,
    deterministic: !!body.deterministic,
    variant: body.variant,
  }, rep);
  const loop = await runAgenticLoop(build, { maxIterations: 3 });
  const audit = auditSiteHtml(loop.html);
  const direction = (body.direction && NX_COMPOSE_DIRECTIONS && NX_COMPOSE_DIRECTIONS[body.direction]) ? String(body.direction) : '';
  return { name, html: loop.html, test: loop.test, audit, iterations: loop.iterations, fixed: loop.fixed, trace: loop.trace, plan: body.plan || null, direction, designExplanation: rep.explanation || '', build: rep.build || null, ast: loop.ast || null, validation: loop.validation || null };
}
// Idempotent, cached schema migration: ensure the canonical `graph` column exists on
// `sites` and `site_versions` so a pre-existing database (created before graph-aware
// versioning) gains it without erroring. Fresh DBs already get it from schema.sql.
let __siteSchemaChecked = false;
async function __ensureSiteGraphColumns(env) {
  if (__siteSchemaChecked || !env || !env.DB) return;
  __siteSchemaChecked = true;
  const cols = ['ALTER TABLE sites ADD COLUMN graph TEXT DEFAULT \'\'', 'ALTER TABLE site_versions ADD COLUMN graph TEXT DEFAULT \'\''];
  for (const sql of cols) {
    try { await env.DB.prepare(sql).run(); }
    catch (e) {
      // Only "duplicate column" is the expected steady state; anything else is a real schema fault.
      if (!/duplicate column|already exists/i.test(String(e && e.message))) logFailure('db.migrate.site_columns', e, { sql: sql.slice(0, 80) });
    }
  }
}

// ── Body / column helpers shared by the public endpoints and the site routes ──
// Public (unauthenticated) JSON bodies: `{}` for an empty body, the parsed
// object, or `null` when the body is not a JSON object — the caller answers 400.
async function readPublicJson(req) {
  let raw = '';
  try { raw = await req.text(); } catch (e) { logSwallow('public.body_read', e); return null; }
  if (raw.length > 200_000) return null;
  if (!raw.trim()) return {};
  try {
    const v = JSON.parse(raw);
    return (v !== null && typeof v === 'object' && !Array.isArray(v)) ? v : null;
  } catch (e) { logSwallow('public.body_parse', e, { sample: raw.slice(0, 60) }); return null; }
}
